#!/usr/bin/env bash
#
# Regenerates the Kouyu app icon source assets, then the per-platform icons.
#
# This script is the single source of truth for the icon's geometry: it emits
# both the human-readable SVG and the PNGs that flutter_launcher_icons consumes.
# Edit the geometry here, never the generated files.
#
# Requires ImageMagick 7 (`brew install imagemagick`).
#
# Usage: tool/generate_icons.sh
set -euo pipefail

cd "$(dirname "$0")/.."

CANVAS=1024
RED="#C8342A"          # keep in sync with kSeedColor in lib/theme.dart
WHITE="#FFFFFF"

# --- The mark -------------------------------------------------------------
# 口 (kǒu, "mouth") with a calligraphic speech flick sweeping off its
# bottom-left corner: mouth + speech = spoken language.
#
# The character is built from its three real strokes rather than as a rounded
# rectangle, because the square corners, the slight inward taper, and the
# bottom stroke's overshoot past the right-hand vertical are what make it read
# as a Hanzi character instead of a generic chat bubble.
#
# The flick hangs below the bottom stroke instead of interrupting it. That
# matters: 口 has to stay closed to still be 口, which is why a solid tail
# fused into the outline does not work here.
#
# Coordinates are design-space on a CANVAS-sized grid. The mark is trimmed and
# recentred below, so these need no hand-centring - only their shape matters.
KOU_L=208; KOU_R=800; KOU_T=152; KOU_B=660
STROKE=84       # stroke thickness
LEAN=14         # inward lean of each vertical, top to bottom
OVERSHOOT=24    # how far the bottom stroke passes the right-hand vertical

# The flick as a brush sweep: it leaves the bottom-left corner, curves down and
# left to a tip at (104,910), then returns up along the underside of the bottom
# stroke. Drawn rather than derived, so it stays one constant - adjust the curve
# by eye, then re-check it at 44px, where the tip is the first thing to break.
FLICK="M 222,656 C 214,742 178,838 104,910 C 210,840 318,750 388,664 Z"

# How much of the canvas the mark spans in the full-bleed icon.
MARK_SPAN=700

# Android guarantees only the central 72dp of a 108dp adaptive foreground, and
# a circle mask inscribes that square. It is the mark's *diagonal* that has to
# fit inside the circle, so the foreground's span is derived from the measured
# mark below rather than hardcoded - the flick widened the mark enough to clip
# the character's corner when this was a fixed number.
SAFE_CIRCLE=$((CANVAS * 72 / 108))

# --- Derived stroke polygons ----------------------------------------------
kou_r_over=$((KOU_R - LEAN + OVERSHOOT))

STROKE_LEFT="$KOU_L,$KOU_T $((KOU_L + STROKE)),$KOU_T \
$((KOU_L + LEAN + STROKE)),$KOU_B $((KOU_L + LEAN)),$KOU_B"
STROKE_TOP="$KOU_L,$KOU_T $KOU_R,$KOU_T \
$KOU_R,$((KOU_T + STROKE)) $KOU_L,$((KOU_T + STROKE))"
STROKE_RIGHT="$KOU_R,$KOU_T $((KOU_R - STROKE)),$KOU_T \
$((KOU_R - LEAN - STROKE)),$KOU_B $((KOU_R - LEAN)),$KOU_B"
STROKE_BOTTOM="$((KOU_L + LEAN)),$((KOU_B - STROKE)) $kou_r_over,$((KOU_B - STROKE)) \
$kou_r_over,$KOU_B $((KOU_L + LEAN)),$KOU_B"

OUT=assets/icon
mkdir -p "$OUT"
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

# Draw the mark alone, on transparency, in raw design coordinates.
magick -size "${CANVAS}x${CANVAS}" xc:none -fill "$WHITE" -stroke none \
  -draw "polygon $STROKE_LEFT" \
  -draw "polygon $STROKE_TOP" \
  -draw "polygon $STROKE_RIGHT" \
  -draw "polygon $STROKE_BOTTOM" \
  -draw "path '$FLICK'" \
  "PNG32:$TMP/mark.png"

# Measure it so every output can scale and centre the mark identically,
# leaving the geometry above free of placement arithmetic.
read -r bw bh bx by <<<"$(magick "$TMP/mark.png" -format '%@' info: \
  | tr 'x+' '   ')"

# place SPAN -> "scale tx ty", fitting the mark's longer side to SPAN
place() {
  awk -v bw="$bw" -v bh="$bh" -v canvas="$CANVAS" -v span="$1" 'BEGIN {
    longest = (bw > bh) ? bw : bh
    s = span / longest
    printf "%.6f %.4f %.4f\n", s, (canvas - bw * s) / 2, (canvas - bh * s) / 2
  }'
}

# The largest span whose scaled diagonal still fits the adaptive safe circle,
# less a few percent so the mark clears the mask edge rather than grazing it.
SAFE_MARGIN=0.96
FOREGROUND_SPAN=$(awk -v bw="$bw" -v bh="$bh" -v safe="$SAFE_CIRCLE" \
  -v margin="$SAFE_MARGIN" 'BEGIN {
  longest = (bw > bh) ? bw : bh
  printf "%d\n", margin * safe * longest / sqrt(bw * bw + bh * bh)
}')

# --- SVG (design source of record) ----------------------------------------
# The transform reproduces the trim-and-centre step exactly, so the SVG and the
# PNGs are the same image, and the geometry stays in readable design coords.
read -r s tx ty <<<"$(place "$MARK_SPAN")"
cat > "$OUT/kouyu_icon.svg" <<SVG
<svg xmlns="http://www.w3.org/2000/svg" width="$CANVAS" height="$CANVAS" viewBox="0 0 $CANVAS $CANVAS">
  <!-- GENERATED by tool/generate_icons.sh - do not edit by hand. -->
  <!-- 口 (kǒu, "mouth") with a speech flick: mouth + speech = spoken language. -->
  <rect width="$CANVAS" height="$CANVAS" fill="$RED"/>
  <g fill="$WHITE" transform="translate($tx,$ty) scale($s) translate(-$bx,-$by)">
    <polygon points="$STROKE_LEFT"/>
    <polygon points="$STROKE_TOP"/>
    <polygon points="$STROKE_RIGHT"/>
    <polygon points="$STROKE_BOTTOM"/>
    <path d="$FLICK"/>
  </g>
</svg>
SVG

compose() { # span background output
  magick "$TMP/mark.png" -trim +repage \
    -resize "$1x$1" \
    -background "$2" -gravity center -extent "${CANVAS}x${CANVAS}" \
    "$3"
}

# Master icon: full-bleed, no alpha channel (the App Store rejects alpha).
compose "$MARK_SPAN" "$RED" "$TMP/master.png"
magick "$TMP/master.png" -alpha remove -alpha off "PNG24:$OUT/kouyu_icon.png"

# Android adaptive foreground: transparent, mark inset for the mask safe zone.
compose "$FOREGROUND_SPAN" none "PNG32:$OUT/kouyu_icon_foreground.png"

echo "Wrote $OUT/kouyu_icon.svg, kouyu_icon.png, kouyu_icon_foreground.png"
echo "  mark ${bw}x${bh}; adaptive span $FOREGROUND_SPAN (safe circle $SAFE_CIRCLE)"

# --- Per-platform icons ----------------------------------------------------
flutter pub run flutter_launcher_icons
